-- Run schema.sql first.
-- This seed uses standalone UUIDs and does not touch auth.users.

on conflict (id) do update set name = excluded.name, gender = excluded.gender, location = excluded.location, profession = excluded.profession, bio = excluded.bio, anchor_role = excluded.anchor_role, avatar_url = excluded.avatar_url, cover_url = excluded.cover_url, feed_count = excluded.feed_count, followers_count = excluded.followers_count, following_count = excluded.following_count;

on conflict (id) do update set video_url = excluded.video_url, thumbnail_url = excluded.thumbnail_url, headline = excluded.headline, location = excluded.location, date_posted = excluded.date_posted, view_count = excluded.view_count, like_count = excluded.like_count, duration_seconds = excluded.duration_seconds;

on conflict (id) do update set follower_name = excluded.follower_name, follower_handle = excluded.follower_handle, follower_avatar_url = excluded.follower_avatar_url, relationship_type = excluded.relationship_type;
